prompt:
你是 C++20 程序员。只输出一个 ```cpp 代码块，不要解释。

写单头文件 mc_gate_rng.h，namespace mc_gate，包含 <cstdint> <cmath> <cstddef>。

【文件结构硬性规则，违反必然编译失败】
- 所有 #include 必须集中在文件最顶部，位于 namespace 之外，一行一个。
- namespace mc_gate { ... } 必须在自检 main 之前用单独的 } 关闭。
- 自检 main 必须是全局作用域的 int main()。
- 若把 #include 写进 namespace 内，<cstdio> 会让 FILE/fopen 等变成 mc_gate::FILE，产生上百行级联错误。

【1】PCG64（XSL-RR 128/64），必须逐位精确：
struct Pcg64 {
  unsigned __int128 state_;
  unsigned __int128 inc_;
  explicit Pcg64(std::uint64_t seed);
  std::uint64_t next();
  double next_double();
};
常量：
  MULT = ((unsigned __int128)0x2360ED051FC65DA4ULL << 64) | 0x4385DF649FCCF645ULL
  INC  = ((unsigned __int128)0x5851F42D4C957F2DULL << 64) | 0x14057B7EF767814FULL
私有 void step_(): state_ = state_ * MULT + INC;
构造 Pcg64(seed): state_=0; inc_=((unsigned __int128)seed<<1)|1; step_(); state_+=seed; step_();
next():
  old = state_; step_();
  std::uint64_t hi=(std::uint64_t)(old>>64), lo=(std::uint64_t)old;
  std::uint64_t xs = hi ^ lo;
  int r = (int)(hi >> 58);
  std::uint64_t rot = ((std::uint64_t)r) & 63ULL;
  return (xs >> rot) | (xs << ((64ULL - rot) & 63ULL));
next_double(): return (double)(next() >> 11) * 0x1.0p-53;

陷阱：禁止 (1u128<<128)-1 之类掩码（128 位移位计数 128 未定义；自然溢出即 mod 2^128）。
禁止 std::normal_distribution。右旋 rot==0 时左移 64 位未定义，必须用 ((64-rot)&63)。

【2】double normal_z(Pcg64& rng) —— Box–Muller，两支顺序固定并缓存：
  u1=rng.next_double(); u2=rng.next_double(); if(u1<1e-300) u1=1e-300;
  r=sqrt(-2.0*log(u1)); th=6.283185307179586*u2;
  首次返回 r*cos(th)，并把 r*sin(th) 存入 static thread_local double 缓存；缓存非空则取出并清空。

【3】double t5_z(Pcg64& rng) —— 标准化 t(5)：
  chi2_5 = z1^2+...+z5^2（五个 normal_z）；
  t = z0 / sqrt(chi2_5/5.0)（z0 是另一次 normal_z）；
  返回 t * sqrt(3.0/5.0)。方差应为 1，超额峰度应约 6。

【4】struct Garch —— 模拟 sigma_t^2 = omega + alpha*a_{t-1}^2 + beta*sigma_{t-1}^2，
                               a_t = sigma_t * z_t，z_t ~ t5_z，alpha=0.08, beta=0.90, omega=0.02。
  成员：double alpha, beta, omega, sigma2, a_prev_sq;
  构造: alpha=0.08; beta=0.90; omega=1.0-0.08-0.90; sigma2=1.0; a_prev_sq=0.0;
  double step(Pcg64& rng)：返回**创新 a_t 本身**（不是它的平方）
     sigma2 = omega + alpha*a_prev_sq + beta*sigma2;
     double sigma = std::sqrt(sigma2);          // 注意：sigma2 是方差，必须开方
     double z = t5_z(rng);
     double a = sigma * z;
     a_prev_sq = a * a;
     return a;
  不变量：E[sigma2] = 1，因 omega=1-alpha-beta；故长期 E[a_t^2] 应约 1。

【5】struct ShortVol —— 成员 double a,b,norm;
  构造: a=1.0;
    用二分法解 b∈[0.0,5.0] 使 skew(b) = -2.5，其中
      skew(b) = -(6.0*a*a*b + 8.0*b*b*b) / pow(a*a + 2.0*b*b, 1.5);
    已知事实：在 b∈[0,5] 上 skew 从 0 单调递减到约 -2.83，故方程唯一根约为 b=0.7071。
    二分必须始终让 lo/hi 夹住根（注意 skew 递减，判断要与单调方向一致），迭代 200 次取中点。
    然后 norm = sqrt(a*a + 2.0*b*b);
  double z(Pcg64& rng): u=normal_z(rng); w=u*u-1.0; return (a*u - b*w)/norm;
    不变量：Var 应为 1（因为 Var(a*u - b*w) = a^2 + 2b^2）。

【6】自检 main，用 #ifdef MC_GATE_RNG_SELFTEST 包住：
  { Pcg64 g(42);    for(int i=0;i<8;++i) std::printf("PCG42 %016llx\n",(unsigned long long)g.next()); }
  { Pcg64 g(12345); for(int i=0;i<8;++i) std::printf("PCG12345 %016llx\n",(unsigned long long)g.next()); }
  { Pcg64 g(7); const int N=2000000; double s1=0,s2=0,s3=0,s4=0;
    for(int i=0;i<N;++i){double x=t5_z(g); s1+=x; s2+=x*x; s3+=x*x*x; s4+=x*x*x*x;}
    double m1=s1/N,m2=s2/N,m3=s3/N,m4=s4/N; double var=m2-m1*m1;
    double mu4=m4-4*m1*m3+6*m1*m1*m2-3*m1*m1*m1*m1;
    std::printf("T5VAR %.9f\n",var); std::printf("T5KURT %.6f\n",mu4/(var*var)-3.0); }
  { ShortVol sv; std::printf("SVB %.12f\n",sv.b); Pcg64 g(11); const int N=2000000;
    double s1=0,s2=0,s3=0,s4=0;
    for(int i=0;i<N;++i){double x=sv.z(g); s1+=x; s2+=x*x; s3+=x*x*x; s4+=x*x*x*x;}
    double m1=s1/N,m2=s2/N,m3=s3/N,m4=s4/N; double var=m2-m1*m1;
    std::printf("SVVAR %.9f\n",var);
    std::printf("SVSKEW %.6f\n",(m3-3*m1*m2+2*m1*m1*m1)/(var*sqrt(var))); }
  { Garch gh; Pcg64 g(13); const int N=2000000; double sa=0;
    for(int i=0;i<N;++i){double a=gh.step(g); sa+=a*a;}
    std::printf("GARCHOMEGA %.12f\n",gh.omega); std::printf("GARCHVAR %.6f\n",sa/N); }
  return 0;

要求：g++ -std=c++20 -O2 -Wall -Wextra 编译零警告。
